using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new Mock<ITempDataProvider>().Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Drain any existing notifications
            while (true)
            {
                var r = _controller.GetNotifications();
                var json = r.Value as dynamic;
                if (json == null) break;
                // Check via reflection
                var type = r.Value!.GetType();
                var countProp = type.GetProperty("count");
                if (countProp != null && (int)countProp.GetValue(r.Value)! == 0) break;
            }

            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            Assert.NotNull(result.Value);
            var resultType = result.Value!.GetType();
            var successProp = resultType.GetProperty("success");
            Assert.True((bool)successProp!.GetValue(result.Value)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            Assert.NotNull(result);
            var resultType = result.Value!.GetType();
            var successProp = resultType.GetProperty("success");
            Assert.True((bool)successProp!.GetValue(result.Value)!);
        }
    }
}

